<?php

namespace Tests\Unit;

use App\Domain\Schema\Canonical;
use App\Domain\Schema\CommandApplier;
use App\Domain\Schema\CommandException;
use App\Domain\Schema\DefinitionValidator;
use App\Domain\Schema\DocumentCodec;
use App\Domain\Data\FieldValue;
use App\Domain\Schema\Rules;
use App\Domain\Schema\Upcaster;
use PHPUnit\Framework\Attributes\DataProvider;
use Tests\TestCase;

/**
 * Parity with the TypeScript reference implementation (packages/app-schema).
 * Fixtures are generated by `npm run fixtures -w packages/app-schema`.
 */
class SchemaParityTest extends TestCase
{
    private static function fixture(string $name): array
    {
        $path = dirname(__DIR__, 4).'/packages/app-schema/fixtures/'.$name;

        return json_decode((string) file_get_contents($path), true, 128, JSON_THROW_ON_ERROR);
    }

    private static function canonical(array $doc): string
    {
        return DocumentCodec::encode($doc);
    }

    public function test_initial_fixture_is_valid(): void
    {
        $this->assertSame([], DefinitionValidator::validate(self::fixture('initial.json')));
    }

    public static function commandCases(): array
    {
        $cases = [];
        foreach (self::fixture('commands.json') as $c) {
            $cases[$c['name']] = [$c['commands'], $c['expected']];
        }

        return $cases;
    }

    #[DataProvider('commandCases')]
    public function test_command_application_matches_typescript(array $commands, array $expected): void
    {
        $result = CommandApplier::applyAll(self::fixture('initial.json'), $commands);
        $this->assertSame(self::canonical($expected), self::canonical($result));
        $this->assertSame([], DefinitionValidator::validate($result));
    }

    public static function errorCases(): array
    {
        $cases = [];
        foreach (self::fixture('command-errors.json') as $c) {
            $cases[$c['name']] = [$c['commands'], $c['errorCode']];
        }

        return $cases;
    }

    #[DataProvider('errorCases')]
    public function test_command_errors_match_typescript(array $commands, string $code): void
    {
        try {
            CommandApplier::applyAll(self::fixture('initial.json'), $commands);
            $this->fail('expected CommandException');
        } catch (CommandException $e) {
            $this->assertSame($code, $e->errorCode);
        }
    }

    public static function invalidDocuments(): array
    {
        $cases = [];
        foreach (self::fixture('invalid-documents.json') as $c) {
            $cases[$c['name']] = [$c['document'], $c['codes']];
        }

        return $cases;
    }

    #[DataProvider('invalidDocuments')]
    public function test_invalid_documents_are_rejected_with_same_codes(array $doc, array $codes): void
    {
        $found = array_values(array_unique(array_column(DefinitionValidator::validate($doc), 'code')));
        sort($found);
        $this->assertSame($codes, $found);
    }

    public function test_structural_validation_rejects_reserved_sections_and_unknown_keys(): void
    {
        $doc = self::fixture('initial.json');
        $doc['actions'] = [['name' => 'x']];
        $doc['evil'] = true;
        $codes = array_column(DefinitionValidator::validate($doc), 'code');
        $this->assertContains('schema.maxItems', $codes);
        $this->assertContains('schema.additionalProperties', $codes);
    }

    public function test_canonical_encoding_is_stable_and_keeps_empty_objects(): void
    {
        $doc = self::fixture('initial.json');
        $json = DocumentCodec::encode($doc);
        $this->assertStringContainsString('"props":{}', $json);
        $this->assertSame($json, DocumentCodec::encode(DocumentCodec::decode($json)));
        $shuffled = $doc;
        $shuffled['components'] = array_reverse($shuffled['components'], true);
        $this->assertSame(DocumentCodec::hash($json), DocumentCodec::hash(DocumentCodec::encode($shuffled)));
        $this->assertIsArray(Canonical::sort(['b' => 1, 'a' => 2]));
    }

    public function test_field_values_match_typescript_table(): void
    {
        foreach (self::fixture('field-values.json') as $c) {
            $this->assertSame($c['ok'], FieldValue::validate($c['field'], $c['value']) === null, json_encode($c, JSON_UNESCAPED_UNICODE));
        }
    }

    public function test_v1_documents_are_upcast(): void
    {
        $doc = self::fixture('initial.json');
        $doc['schemaVersion'] = 1;
        $this->assertNotSame([], DefinitionValidator::validate($doc));
        $this->assertSame([], DefinitionValidator::validate(Upcaster::upcast($doc)));
    }

    public function test_href_safety_matches_typescript_table(): void
    {
        $table = [
            ['/', true], ['/about-us?x=1#top', true], ['#contact', true], ['https://example.com/a?b=c', true],
            ['mailto:hello@example.com', true], ['tel:+66 2 123 4567', true],
            ['javascript:alert(1)', false], ['JAVASCRIPT:alert(1)', false], ['//evil.com', false], ['data:text/html,x', false],
            ['/\\evil', false], ['https://exa mple.com', false], ['', false], ['vbscript:x', false],
        ];
        foreach ($table as [$href, $ok]) {
            $this->assertSame($ok, Rules::isSafeHref($href), $href);
        }
    }
}
